<script lang="ts">
 import { onMount } from 'svelte';import { db } from '$lib/db';import type { Drawing, Stage } from '$lib/types';import CompareSlider from '$lib/components/CompareSlider.svelte';
 let month=$state(new Date().toISOString().slice(0,7)),drawings=$state<{drawing:Drawing;first:Stage;latest:Stage}[]>([]),urlMap=$state<Record<string,string>>({}),error=$state('');
 async function refresh(){const [y,m]=month.split('-').map(Number),start=new Date(y,m-1,1).getTime(),end=new Date(y,m,1).getTime(),all=await db.drawings.toArray(),out=[] as {drawing:Drawing;first:Stage;latest:Stage}[];for(const drawing of all){const stages=await db.stages.where('drawingId').equals(drawing.id).sortBy('createdAt'),inMonth=stages.filter(s=>s.createdAt>=start&&s.createdAt<end);if(inMonth.length)out.push({drawing,first:inMonth[0],latest:inMonth.at(-1)!});}urlMap=Object.fromEntries(out.flatMap(x=>[[x.first.id,URL.createObjectURL(x.first.flatBlob)],[x.latest.id,URL.createObjectURL(x.latest.flatBlob)]]));drawings=out;}
 onMount(()=>{void refresh();});
</script>
<div class="app"><header class="topbar"><a class="brand" href="/"><span class="brand-mark">✳</span>Skepanion</a><nav class="nav"><a href="/">Drawings</a><a href="/palettes">My colors</a></nav></header><p class="eyebrow">A month in the making</p><h1>Monthly progress</h1><p class="muted">Compare the first and latest photo for each drawing you worked on this month.</p><div class="field" style="max-width:240px"><label for="month">Choose a month</label><input id="month" type="month" bind:value={month} onchange={()=>void refresh()}/></div>
{#if error}<p>{error}</p>{:else if drawings.length}<div class="grid">{#each drawings as item}<article class="card"><h2>{item.drawing.title}</h2><p class="muted">{new Date(item.first.createdAt).toLocaleDateString()} → {new Date(item.latest.createdAt).toLocaleDateString()}</p>{#if item.first.id!==item.latest.id}<CompareSlider before={urlMap[item.first.id]} after={urlMap[item.latest.id]} label={`Monthly comparison for ${item.drawing.title}`}/>{:else}<img src={urlMap[item.first.id]} alt={`Only stage for ${item.drawing.title}`} style="width:100%;border-radius:14px"/>{/if}</article>{/each}</div>{:else}<div class="card empty-card"><div style="font-size:40px">🗓️</div><h2>No stages for this month yet</h2><p class="muted">Add a progress photo and it will appear here.</p></div>{/if}</div>
